import test from 'node:test';
import assert from 'node:assert';
import { createState, frame, collides, BALL_R, BRICK_H } from '../game/neon.js';

const mockCtx = {
  fillRect: () => {},
  fillText: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
};

test('D1: Ball should bounce off the top of a brick', () => {
  const state = createState(1);
  state.ball = { x: 100, y: 50, r: BALL_R, vx: 0, vy: 100 };
  const brick = state.bricks[0];
  brick.x = 80; brick.y = 60; brick.w = 72; brick.h = BRICK_H;

  // Ensure collision is detected
  assert.strictEqual(collides(state.ball, brick), true);

  frame(mockCtx, state);

  assert.ok(state.ball.vy < 0, 'Ball should have bounced upward');
});

test('D2: Ball should not stick to the brick (re-collision on next frame)', () => {
  const state = createState(1);
  // Position ball so it's already overlapping the brick
  state.ball = { x: 100, y: 65, r: BALL_R, vx: 0, vy: 100 };
  const brick = state.bricks[0];
  brick.x = 80; brick.y = 60; brick.w = 72; brick.h = BRICK_H;

  frame(mockCtx, state);
  const vyAfterFirstHit = state.ball.vy;
  assert.ok(vyAfterFirstHit < 0, 'First bounce failed');

  // Simulate another frame where the ball is still overlapping
  frame(mockCtx, state);
  assert.ok(state.ball.vy < 0, 'Ball should not have re-inverted its velocity (stuck)');
});

test('D4: Ball should bounce off the side of a brick', () => {
  const state = createState(1);
  state.ball = { x: 70, y: 65, r: BALL_R, vx: 100, vy: 0 };
  const brick = state.bricks[0];
  brick.x = 80; brick.y = 60; brick.w = 72; brick.h = BRICK_H;

  assert.strictEqual(collides(state.ball, brick), true);

  frame(mockCtx, state);

  assert.ok(state.ball.vx < 0, 'Ball should have bounced leftward');
});

