import test from 'node:test';
import assert from 'node:assert/strict';
import { createState, frame, collides, BALL_R, BRICK_H } from './neon.js';

const mockCtx = {
  fillRect: () => {},
  fillText: () => {},
  beginPath: () => {},
  arc: () => {},
  fill: () => {},
};

test('D1: Ball should bounce off the top of a brick', () => {
  const state = createState(1);
  state.ball = { x: 100, y: 50, r: BALL_R, vx: 0, vy: 100 };
  const brick = state.bricks[0];
  brick.x = 80; brick.y = 60; brick.w = 72; brick.h = BRICK_H;

  frame(mockCtx, state);

  assert.ok(state.ball.vy < 0, 'Ball should have bounced upward');
});

test('D2: Ball should not stick to the brick (re-collision on next frame)', () => {
  const state = createState(1);
  state.ball = { x: 100, y: 65, r: BALL_R, vx: 0, vy: 100 };
  const brick = state.bricks[0];
  brick.x = 80; brick.y = 60; brick.w = 72; brick.h = BRICK_H;

  frame(mockCtx, state);
  const vyAfterFirstHit = state.ball.vy;
  assert.ok(vyAfterFirstHit < 0, 'First bounce failed');

  frame(mockCtx, state);
  assert.ok(state.ball.vy < 0, 'Ball should not have re-inverted its velocity (stuck)');
});

test('D4: Ball should bounce off the side of a brick', () => {
  const state = createState(1);
  state.ball = { x: 70, y: 65, r: BALL_R, vx: 100, vy: 0 };
  const brick = state.bricks[0];
  brick.x = 80; brick.y = 60; brick.w = 72; brick.h = BRICK_H;

  frame(mockCtx, state);

  assert.ok(state.ball.vx < 0, 'Ball should have bounced leftward');
});

test('D3: Ball should not double-invert when hitting two bricks at once', () => {
  const state = createState(1);
  state.ball = { x: 100, y: 60, r: BALL_R, vx: 0, vy: 100 };

  state.bricks = [
    { x: 80, y: 60, w: 72, h: BRICK_H, alive: true },
    { x: 80, y: 60, w: 72, h: BRICK_H, alive: true },
  ];

  frame(mockCtx, state);

  assert.ok(state.ball.vy < 0, 'Ball should have bounced upward once');
});

edits.newText:
if (collides(state.ball, brick)) {
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);

  // Resolution: bounce the ball based on the axis of least penetration
  const overlapX = Math.min(
    (state.ball.x + state.ball.r) - brick.x,
    (brick.x + brick.w) - (state.ball.x - state.ball.r)
  );
  const overlapY = Math.min(
    (state.ball.y + state.ball.r) - brick.y,
    (brick.y + brick.h) - (state.ball.y - state.ball.r)
  );

  if (overlapX < overlapY) {
    // Horizontal bounce: only if moving towards the brick
    if ((state.ball.vx > 0 && state.ball.x < brick.x) || 
        (state.ball.vx < 0 && state.ball.x > brick.x + brick.w)) {
      state.ball.vx = -state.ball.vx;
    }
    // Reposition to avoid sticking
    state.ball.x = state.ball.vx > 0 ? brick.x + brick.w + state.ball.r : brick.x - state.ball.r;
  } else {
    // Vertical bounce: only if moving towards the brick
    if ((state.ball.vy > 0 && state.ball.y < brick.y) || 
        (state.ball.vy < 0 && state.ball.y > brick.y + brick.h)) {
      state.ball.vy = -state.ball.vy;
    }
    // Reposition to avoid sticking
    state.ball.y = state.ball.vy > 0 ? brick.y + brick.h + state.ball.r : brick.y - state.ball.r;
  }
}

